add_filter( 'woocommerce_get_availability_text', 'perfectpixel_stock_quantity_text', 20, 2 );

function perfectpixel_stock_quantity_text( $text, $product ) {
	if ( $product && $product->managing_stock() && $product->is_in_stock() && ! $product->is_on_backorder( 1 ) && $product->get_stock_quantity() > 0 ) {
		return str_replace( '{qty}', wc_stock_amount( $product->get_stock_quantity() ), '{{stock_qty_text}}' );
	}
	return $text;
}
